import java.util.*;
import java.io.*;

public class Main {
    static final int P = 998244353;
    static final int MOD = 1000000007;
    static final int B = 1000000;
    static long n_value, total_count;
    static long[] prefix_sum = new long[7];
    static int result;
    static List<Integer>[] sequences = new ArrayList[7];

    static {
        for (int i = 0; i < 7; i++) {
            sequences[i] = new ArrayList<>();
        }
    }

    static int normalize(long d) {
        long res = d % P;
        if (res < 0) res += P;
        return (int) res;
    }

    static void build_sequences(int level, long val) {
        total_count++;
        sequences[level].add(normalize(total_count - val));
        if (level < 6) {
            for (int i = 0; i <= 9; i++) {
                build_sequences(level + 1, val * 10 + i);
            }
        }
    }

    static int get_value(int id, int f) {
        List<Integer> seq = sequences[id];
        int pos = lowerBound(seq, P - f);
        long sumSeq = prefix_sum[id];
        long size = seq.size();
        long res = ((long)f * size + sumSeq - (long)P * (size - pos)) % MOD;
        if (res < 0) res += MOD;
        return (int) res;
    }

    static int lowerBound(List<Integer> list, int key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    static void traverse(int depth, long v) {
        if (v > n_value) return;
        if (depth >= 1) {
            if (v * B > n_value / 10 && v * B + B - 1 <= n_value) {
                int t = 1;
                for (int i = 0; i <= 6; i++) {
                    result = (result + normalize(total_count - (int) v * t)) % MOD;
                    t *= 10;
                }
                for (int i = 0; i <= 6; i++) {
                    total_count += sequences[i].size();
                }
                return;
            }
            result = (result + normalize(total_count - (int) v)) % MOD;
        }
        int start = (depth == 0) ? 0 : 0;
        for (int i = start; i <= 9; i++) {
            traverse(depth + 1, v * 10 + i);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n_value = Long.parseLong(br.readLine().trim());
        build_sequences(0, 0);
        for (int i = 0; i <= 6; i++) {
            Collections.sort(sequences[i]);
            long sum = 0;
            for (int val : sequences[i]) {
                sum += val;
            }
            prefix_sum[i] = sum;
        }
        total_count = 0;
        result = 0;
        traverse(0, 0);
        System.out.println(result);
    }
}
